SELECT rate_type, COUNT(*) FILTER (WHERE lvr_at_origination_pct<=70), COUNT(*) FILTER (WHERE lvr_at_origination_pct>70 AND lvr_at_origination_pct<=80), COUNT(*) FILTER (WHERE lvr_at_origination_pct>80 AND lvr_at_origination_pct<=90), COUNT(*) FILTER (WHERE lvr_at_origination_pct>90) FROM loan WHERE channel='Broker' GROUP BY 1 ORDER BY 1
